  let fighter={data,team,root,model,body,armL,armR,gloveL,gloveR,legLeft,legRight,health:data.hp,maxHealth:data.hp,attackCd:Math.random()*.6,stun:0,alive:true,home:new THREE.Vector3(x,0,z),phase:Math.random()*6,knock:new THREE.Vector3(),nameTag};fighters.push(fighter);return fighter;
