function startBattle(){if(selected.size===0){toast('Choose at least one contender first');return}$('#select-screen').classList.add('hidden');$('#battle-screen').classList.remove('hidden');$('#result-modal').classList.add('hidden');$('#touch-controls').style.display=matchMedia('(pointer:coarse)').matches||innerWidth<700?'block':'none';mode='battle';elapsed=0;$('#battle-timer').textContent='00:00';fighters.forEach(f=>scene.remove(f.root));fighters=[];if(preview){scene.remove(preview.root);preview=null}let blues=roster.filter(f=>selected.has(f.id)),reds=roster.filter(f=>!selected.has(f.id));if(!reds.length)reds=[roster.find(f=>!selected.has(f.id))||roster[6]];
  blues.forEach((f,i)=>createFighter(f,'blue',-2.6+i*2.35,2.1));reds.forEach((f,i)=>createFighter(f,'red',-2.4+i*2.35,-2.05));activeIndex=0;setActive();$('#blue-score').textContent=`${blues.length} / ${blues.length}`;$('#red-score').textContent=`${reds.length} / ${reds.length}`;$('#battle-banner').classList.remove('hidden');$('#banner-text').textContent='LET’S GET THIS PARTY STARTED';setTimeout(()=>$('#battle-banner').classList.add('hidden'),1800);updateHealth();playTone(540,.13);}
function setActive(){let active=fighters.filter(f=>f.team==='blue'&&f.alive);if(!active.length)return;activeIndex=Math.max(0,Math.min(activeIndex,active.length-1));$('#active-name').textContent=active[activeIndex].data.name.toUpperCase();}
function currentPlayer(){return fighters.filter(f=>f.team==='blue'&&f.alive)[activeIndex]}
function switchPlayer(n){let a=fighters.filter(f=>f.team==='blue'&&f.alive);if(!a.length)return;activeIndex=(n+a.length)%a.length;setActive();toast(`GO, ${a[activeIndex].data.name.toUpperCase()}!`)}
function startAttack(f){if(!f||f.attackCd>0||!f.alive)return;f.attackCd=f.data.rate;f.attackAnim=.32;playTone(f.team==='blue'?390:270,.06);let foes=fighters.filter(o=>o.team!==f.team&&o.alive);let target=null,dist=2.1;for(let e of foes){let d=f.root.position.distanceTo(e.root.position);if(d<dist){dist=d;target=e}}if(target){let dir=target.root.position.clone().sub(f.root.position).normalize();target.health-=f.data.damage;target.stun=.22;target.knock.add(dir.multiplyScalar(.6));target.root.position.addScaledVector(dir,.24);floatText(target.root,`-${f.data.damage}`,f.team==='blue'?'#a7f1ff':'#ffaca3');if(target.health<=0){target.health=0;target.alive=false;target.root.visible=false;target.knock.set(0,0,0);playTone(160,.22);checkEnd()}updateHealth()}else{f.missAnim=.2}}
function floatText(parent,text,color){let s=makeTextSprite(text,color,'#172230');s.position.set((Math.random()-.5)*.4,2.65,.15);s.scale.set(.55,.3,1);parent.add(s);setTimeout(()=>parent.remove(s),600)}
function updateHealth(){let sides=['blue','red'];for(let side of sides){let live=fighters.filter(f=>f.team===side&&f.alive);$('#'+side+'-score').textContent=`${live.length} / ${fighters.filter(f=>f.team===side).length}`;let el=$('#'+side+'-health');el.innerHTML='';fighters.filter(f=>f.team===side).forEach(f=>{let seg=document.createElement('span');seg.className='health-segment';seg.innerHTML=`<i style="width:${Math.max(0,f.health/f.maxHealth*100)}%;${!f.alive?'opacity:0':''}"></i>`;el.appendChild(seg)})}}
function checkEnd(){if(mode!=='battle')return;let b=fighters.some(f=>f.team==='blue'&&f.alive),r=fighters.some(f=>f.team==='red'&&f.alive);if(!b||!r){mode='result';setTimeout(()=>{let win=b;$('#result-icon').textContent=win?'✦':'♡';$('#result-title').textContent=win?'VICTORY!':'GOOD GAME!';$('#result-copy').textContent=win?'The crowd is absolutely losing it. What a crew!':'The challengers got this round. Give it another go!';$('#result-modal').classList.remove('hidden');playTone(win?650:210,.2)},450)}}
function resetBattle(){mode='select';$('#result-modal').classList.add('hidden');$('#battle-screen').classList.add('hidden');$('#select-screen').classList.remove('hidden');fighters.forEach(f=>scene.remove(f.root));fighters=[];renderRoster();showcase(activeIndex)}
function update(dt){let t=clock.getElapsedTime();if(mode==='battle'){elapsed+=dt;$('#battle-timer').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;let player=currentPlayer();for(let f of fighters){if(!f.alive)continue;f.attackCd=Math.max(0,f.attackCd-dt);f.stun=Math.max(0,f.stun-dt);f.phase+=dt*6;let isPlayer=f===player;let target=f.team==='blue'?fighters.filter(e=>e.team==='red'&&e.alive):fighters.filter(e=>e.team==='blue'&&e.alive);let closest=null,dist=1e9;for(let e of target){let d=f.root.position.distanceTo(e.root.position);if(d<dist){dist=d;closest=e}}
      let dx=0,dz=0;if(isPlayer){dx=input.x;dz=input.z;if(dx||dz){let l=Math.hypot(dx,dz);dx/=l;dz/=l}}else if(closest){let tx=closest.root.position.x-f.root.position.x,tz=closest.root.position.z-f.root.position.z,dl=Math.hypot(tx,tz)||1;if(dist>1.18){dx=tx/dl;dz=tz/dl}else if(f.attackCd<=0&&Math.random()<dt*2.5)startAttack(f)}
      if(f.stun<=0){let speed=f.data.speed*(isPlayer?1:0.76);f.root.position.x+=dx*speed*dt;f.root.position.z+=dz*speed*dt;}f.root.position.addScaledVector(f.knock,dt*4);f.knock.multiplyScalar(Math.max(0,1-dt*4));f.root.position.x=THREE.MathUtils.clamp(f.root.position.x,-5.05,5.05);f.root.position.z=THREE.MathUtils.clamp(f.root.position.z,-3.65,3.65);
      if(dx||dz){f.root.rotation.y=Math.atan2(dx,dz);f.model.position.y=Math.abs(Math.sin(f.phase))*0.07;f.legLeft.rotation.x=Math.sin(f.phase)*.58;f.legRight.rotation.x=-Math.sin(f.phase)*.58}else{f.model.position.y=Math.sin(t*2.4+f.phase)*.018;f.legLeft.rotation.x=0;f.legRight.rotation.x=0}f.armL.rotation.z=-.42+Math.sin(t*2+f.phase)*.025;f.armR.rotation.z=.42-Math.sin(t*2+f.phase)*.025;
      if(f.attackAnim>0){f.attackAnim-=dt;let p=Math.max(0,f.attackAnim/.32);f.armR.rotation.x=-Math.sin((1-p)*Math.PI)*1.5;f.gloveR.position.z=.07+Math.sin((1-p)*Math.PI)*.45}else{f.armR.rotation.x=0;f.gloveR.position.z=.07}
    }
  }else if(mode==='select'&&preview){preview.model.rotation.y=Math.sin(t*.55)*.12;preview.model.position.y=Math.sin(t*2.4)*.03;preview.armR.rotation.z=.42+Math.sin(t*2)*.04}
  if(mode==='battle'){let p=currentPlayer();if(p){let c=new THREE.Vector3(p.root.position.x*.18,1.1,p.root.position.z*.12);camera.position.x=THREE.MathUtils.lerp(camera.position.x,c.x,.025);camera.lookAt(c)}}renderer.render(scene,camera);}
