function resize(){if(!renderer)return;renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<650?43:36;camera.updateProjectionMatrix();$('#touch-controls').style.display=mode==='battle'&&(matchMedia('(pointer:coarse)').matches||innerWidth<700)?'block':'none'}
function keyDown(e){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();let k=e.key.toLowerCase();if(k==='w'||k==='arrowup')input.z=-1;if(k==='s'||k==='arrowdown')input.z=1;if(k==='a'||k==='arrowleft')input.x=-1;if(k==='d'||k==='arrowright')input.x=1;if(e.code==='Space'){input.attack=true;startAttack(currentPlayer())}if(mode==='battle'&&/^[1-3]$/.test(e.key))switchPlayer(Number(e.key)-1)}
function keyUp(e){let k=e.key.toLowerCase();if((k==='w'||k==='arrowup')&&input.z<0)input.z=0;if((k==='s'||k==='arrowdown')&&input.z>0)input.z=0;if((k==='a'||k==='arrowleft')&&input.x<0)input.x=0;if((k==='d'||k==='arrowright')&&input.x>0)input.x=0;if(e.code==='Space')input.attack=false}
function playTone(freq,duration){if(!soundOn)return;try{audioCtx ||= new AudioContext();let osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(.075,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch{}}
function bindJoystick(){let j=$('#joystick'),knob=$('#joy-knob'),active=false;function move(e){if(!active)return;let r=j.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=32,l=Math.hypot(dx,dy);if(l>max){dx=dx/l*max;dy=dy/l*max}knob.style.transform=`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px))`;input.x=dx/max;input.z=dy/max}function stop(){active=false;input.x=input.z=0;knob.style.transform='translate(-50%,-50%)'}j.addEventListener('pointerdown',e=>{active=true;j.setPointerCapture(e.pointerId);move(e)});j.addEventListener('pointermove',move);j.addEventListener('pointerup',stop);j.addEventListener('pointercancel',stop);$('#attack-button').addEventListener('pointerdown',e=>{e.preventDefault();startAttack(currentPlayer());$('#attack-button').classList.add('pressed')});for(let ev of ['pointerup','pointercancel','pointerleave'])$('#attack-button').addEventListener(ev,()=>$('#attack-button').classList.remove('pressed'))}
function bind(){renderRoster();showcase(0);$('#prev-character').onclick=()=>showcase(activeIndex-1);$('#next-character').onclick=()=>showcase(activeIndex+1);$('#start-button').onclick=startBattle;$('#exit-button').onclick=resetBattle;$('#back-to-select').onclick=resetBattle;$('#rematch-button').onclick=startBattle;$('#sound-toggle').onclick=()=>{soundOn=!soundOn;$('#sound-toggle').innerHTML=soundOn?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>';if(soundOn)playTone(500,.1)};bindJoystick()}
