import * as THREE from '../vendor/three.module.js';

const roster = [
  {id:'huseyin',name:'Hüseyin',type:'THE STEADY ONE',bio:'A patient, grounded fighter. He takes his time, then makes every hit count.',color:'#4fa4bd',skin:'#bd8265',hair:'#322a2b',speed:2.05,damage:7,rate:1.55,hp:112,size:1.02,stats:[['POWER',38],['SPEED',28],['GRIT',76]],role:'Slow & steady',emoji:'🧿',build:'average',hairStyle:'short'},
