  {id:'prof',name:'Professor Plump',type:'THE QUICK THINKER',bio:'Tall, bespectacled and surprisingly nimble. A flurry of average-sized bonks.',color:'#6e9a72',skin:'#d7aa83',hair:'#534d47',speed:3.55,damage:10,rate:.75,hp:110,size:1.12,stats:[['POWER',58],['SPEED',89],['GRIT',78]],role:'Fast hitter',emoji:'⚡',build:'big',hairStyle:'side',glasses:true},
  {id:'pip',name:'Pip',type:'THE POCKET ROCKET',bio:'The tiniest contender in the club. Pip swings for the stars, even if it takes a while.',color:'#f1a94d',skin:'#f0c49d',hair:'#6c402e',speed:3.65,damage:4,rate:1.45,hp:71,size:.57,stats:[['POWER',20],['SPEED',93],['GRIT',35]],role:'Tiny & speedy',emoji:'✨',build:'tiny',hairStyle:'spikes'},
  {id:'curly',name:'Curly',type:'THE UNSTOPPABLE',bio:'A springy curly-haired crowd favorite. One leg short, on spirit never short.',color:'#56a9a0',skin:'#a96e50',hair:'#33251f',speed:2.8,damage:11,rate:1.22,hp:101,size:.94,stats:[['POWER',61],['SPEED',62],['GRIT',70]],role:'Never gives up',emoji:'🌀',build:'average',hairStyle:'curls',oneLeg:true},
  {id:'zaragana',name:'Zaragana',type:'THE QUIET STORM',bio:'A calm competitor with a big heart. Underestimate Zaragana at your own peril.',color:'#697cc9',skin:'#623f38',hair:'#201c21',speed:2.9,damage:7,rate:1.3,hp:99,size:.98,stats:[['POWER',41],['SPEED',66],['GRIT',67]],role:'Calm & clever',emoji:'🌙',build:'average',hairStyle:'short'}
];
const $=s=>document.querySelector(s), sceneCanvas=$('#scene');
let renderer,scene,camera,clock,fighters=[],activeIndex=0,selected=new Set(['huseyin']),mode='select',soundOn=true,elapsed=0,lastToast=0;
const input={x:0,z:0,attack:false};let audioCtx,preview=null;
