  scene.add(new THREE.HemisphereLight(0xd7f1ff,0x443746,2.1));let key=new THREE.DirectionalLight(0xffe6be,3.2);key.position.set(-5,12,8);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-12;key.shadow.camera.right=12;key.shadow.camera.top=12;key.shadow.camera.bottom=-12;scene.add(key);let fill=new THREE.DirectionalLight(0x7bbfe2,1.7);fill.position.set(6,5,-5);scene.add(fill);
