  box(scene,0,-.52,0,42,.35,42,mat(0x253947));box(scene,0,-.18,0,12,.28,9.3,mat(0xc8b995));
  for(let i=0;i<8;i++)for(let j=0;j<6;j++)if((i+j)%2===0)box(scene,-5.25+i*1.5,-.025,-3.85+j*1.5,1.5,.025,1.5,mat(0xd5c8a9));box(scene,0,-.34,0,12.5,.22,9.8,mat(0xe4a957));
