function makeTextSprite(text,fg='#ffffff',bg='transparent'){let c=document.createElement('canvas');c.width=512;c.height=128;let x=c.getContext('2d');if(bg!=='transparent'){x.fillStyle=typeof bg==='number'?'#263344':bg;x.fillRect(0,0,c.width,c.height)}x.fillStyle=typeof fg==='number'?'#ffd26b':fg;x.font='900 58px Outfit, sans-serif';x.textAlign='center';x.textBaseline='middle';x.fillText(text,256,64);let tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;return new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false}))}
