  let round=data.build==='round'||data.build==='big';let body=ball(model,0,1.08,0,round?.55:.42,round?.61:.52,.37,cloth);body.name='body';if(data.shirt){let badge=makeTextSprite(data.shirt,'#ffffff','#c952b0');badge.position.set(0,1.19,.385);badge.scale.set(.51,.21,1);model.add(badge)}
